package in.paisa.personal;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.os.Build;
import android.provider.*;
import android.webkit.JavascriptInterface;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;
import java.time.*;

public class NativeBridge {
 private final MainActivity host;private final ExecutorService worker;
 public NativeBridge(MainActivity h,ExecutorService w){host=h;worker=w;}
 private String error(Exception e){return "{\"ok\":false,\"error\":"+JSONObject.quote(e.getMessage()==null?"Please try again":e.getMessage())+"}";}
 private String text(JSONObject o,String key,int length){String s=o.optString(key,"").trim();if(s.length()>length)throw new IllegalArgumentException(key+" is too long");return s;}
 private boolean granted(String p){return host.checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED;}
 private JSONObject patch(String table,JSONObject row)throws Exception{return new JSONObject().put("table",table).put("row",row);}
 @JavascriptInterface public String getData(){try(Store store=new Store(host)){
  JSONObject state=store.snapshot();JSONArray entries=store.entries();for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);String key=e.optString("merchantKey",e.optString("source").equals("SMS")?SmsParser.nameKey(e.optString("title")):"");e.put("merchantKey",key).put("note",e.optString("note")).put("remembered",!store.learned(key).isEmpty());}
  JSONObject undo=store.lastUndo();String listeners=Settings.Secure.getString(host.getContentResolver(),"enabled_notification_listeners");return state.put("entries",entries).put("safetyBackup",new java.io.File(host.getFilesDir(),"pre-restore.paisabackup").isFile()).put("native",true).put("sms",granted(Manifest.permission.RECEIVE_SMS)).put("readSms",granted(Manifest.permission.READ_SMS)).put("notifications",Build.VERSION.SDK_INT<33||granted(Manifest.permission.POST_NOTIFICATIONS)).put("notificationAccess",listeners!=null&&listeners.contains(host.getPackageName()+"/")).put("undo",undo==null?JSONObject.NULL:new JSONObject().put("id",undo.optString("id")).put("label",undo.optString("label"))).toString();
 }catch(Exception e){return error(e);}}
 private JSONObject cleanEntry(Store store,JSONObject in)throws Exception{
  String id=text(in,"id",120);JSONObject old=id.isEmpty()?null:store.find(id);if(!id.isEmpty()&&old==null)throw new IllegalArgumentException("Entry not found");
  JSONObject row=old==null?new JSONObject():new JSONObject(old.toString());String kind=text(in,"kind",30),accountId=text(in,"accountId",120);JSONObject account=store.get("accounts",accountId);if(account==null)throw new IllegalArgumentException("Choose a payment account");
  row.put("id",id.isEmpty()?UUID.randomUUID().toString():id).put("amount",Ledger.amount(in,"amount",false)).put("kind",kind).put("title",text(in,"title",100)).put("category",text(in,"category",40)).put("person",text(in,"person",80)).put("note",text(in,"note",1000)).put("accountId",accountId).put("account",account.optString("name")).put("toAccountId",text(in,"toAccountId",120)).put("loanId",Ledger.isRepayment(kind)?text(in,"loanId",120):"").put("cardId",kind.equals("card_payment")?text(in,"cardId",120):"").put("subId",kind.equals("expense")?text(in,"subId",120):"").put("date",in.getLong("date")).put("pending",false).put("source",old==null?"Manual":old.optString("source","Manual"));
  row.put("billId",kind.equals("expense")?text(in,"billId",120):"");if(!row.optString("billId").isEmpty()&&store.get("bills",row.optString("billId"))==null)throw new IllegalArgumentException("Linked bill not found");
  if(kind.equals("transfer"))row.put("unresolvedTransfer",false);else if(!kind.equals("card_payment"))row.put("toAccountId","");
  if(old!=null&&(!kind.equals("transfer")||old.optLong("date")!=row.optLong("date")||!old.optString("toAccountId").equals(row.optString("toAccountId"))))row.remove("creditDate");
  row.remove("captureReview");row.put("userEdited",true);
  return row;
 }
 @JavascriptInterface public String save(String raw){try(Store store=new Store(host)){JSONObject in=new JSONObject(raw),old=store.find(in.optString("id")),row=cleanEntry(store,in);JSONArray patches=new JSONArray().put(patch("entries",row));String subId=row.optString("subId");if(!subId.isEmpty()&&(old==null||!subId.equals(old.optString("subId")))){JSONObject sub=store.get("subscriptions",subId);if(sub==null)throw new IllegalArgumentException("Subscription not found");sub.put("nextDue",Ledger.nextDue(sub,row.getLong("date"))).put("lastPaidAt",row.getLong("date"));patches.put(patch("subscriptions",sub));}JSONObject out=store.commit(old==null?"Add entry":"Edit entry",patches);host.getSystemService(NotificationManager.class).cancel(row.getString("id").hashCode());Reminders.schedule(host);worker.execute(()->Reminders.check(host));return out.toString();}catch(Exception e){return error(e);}}
 @JavascriptInterface public String remove(String id){try(Store store=new Store(host)){JSONObject row=store.find(id);if(row==null)throw new IllegalArgumentException("Entry not found");return store.commit("Delete entry",new JSONArray().put(patch("entries",row.put("deleted",true)))).toString();}catch(Exception e){return error(e);}}
 @JavascriptInterface public String bulk(String raw){try(Store store=new Store(host)){JSONObject in=new JSONObject(raw);JSONArray ids=in.getJSONArray("ids"),patches=new JSONArray();if(ids.length()<1||ids.length()>500)throw new IllegalArgumentException("Select 1–500 entries");Set<String> seen=new HashSet<>();String operation=in.getString("operation"),category=text(in,"category",40);for(int i=0;i<ids.length();i++){String id=ids.getString(i);if(!seen.add(id))continue;JSONObject row=store.find(id);if(row==null||row.optBoolean("deleted"))throw new IllegalArgumentException("One selected record no longer exists");if(operation.equals("delete"))row.put("deleted",true);else if(operation.equals("category")){if(category.isEmpty())throw new IllegalArgumentException("Choose a category");if(!Arrays.asList("expense","refund","income").contains(row.optString("kind")))throw new IllegalArgumentException("Choose expenses/income for category correction");row.put("category",category).put("pending",false).put("userEdited",true);row.remove("captureReview");}else throw new IllegalArgumentException("Unknown bulk action");patches.put(patch("entries",row));}return store.commit(operation.equals("delete")?"Bulk delete":"Bulk category correction",patches).toString();}catch(Exception e){return error(e);}}
 @JavascriptInterface public String undo(String id){try(Store store=new Store(host)){store.undo(id);return "{\"ok\":true}";}catch(Exception e){return error(e);}}
 @JavascriptInterface public String linkTransfer(String raw){try(Store store=new Store(host)){JSONObject in=new JSONObject(raw);return store.commit("Link own-account transfer",TransferLink.patches(store.entries(),in.getString("firstId"),in.getString("secondId"))).toString();}catch(Exception e){return error(e);}}
 @JavascriptInterface public String resolveDuplicate(String raw){try(Store store=new Store(host)){JSONObject in=new JSONObject(raw),row=store.find(in.getString("id"));if(row==null||row.optString("duplicateOf").isEmpty())throw new IllegalArgumentException("No duplicate to review");JSONArray changes=new JSONArray();if(in.optBoolean("keep")){row.remove("duplicateOf");changes.put(patch("entries",row));}else{JSONObject original=store.find(row.getString("duplicateOf"));if(original==null||original.optBoolean("deleted"))throw new IllegalArgumentException("Original entry no longer exists");String note=original.optString("note"),newNote=row.optString("note");if(!newNote.isEmpty()&&!note.contains(newNote))original.put("note",(note.isEmpty()?"":note+"\n")+newNote);JSONArray sources=original.optJSONArray("sources");if(sources==null)sources=new JSONArray().put(original.optString("source"));sources.put(row.optString("source"));original.put("sources",sources);changes.put(patch("entries",original)).put(patch("entries",row.put("deleted",true)));}return store.commit("Resolve duplicate",changes).toString();}catch(Exception e){return error(e);}}
 @JavascriptInterface public String saveEntity(String raw){try(Store store=new Store(host)){
  JSONObject in=new JSONObject(raw),x=in.getJSONObject("row");String table=in.getString("table"),id=text(x,"id",120);JSONObject old=id.isEmpty()?null:store.get(table,id);if(!id.isEmpty()&&old==null)throw new IllegalArgumentException("Record not found");JSONObject row=new JSONObject().put("id",id.isEmpty()?UUID.randomUUID().toString():id).put("name",text(x,"name",80));
  if(table.equals("accounts")){row.put("type",text(x,"type",10));long opening=new java.math.BigDecimal(x.get("opening").toString()).longValueExact();if(Math.abs(opening)>Ledger.MAX)throw new IllegalArgumentException("Invalid opening balance");row.put("opening",opening).put("openingAt",x.optLong("openingAt",0));if(old!=null&&old.has("snapshot")&&!x.optBoolean("clearSnapshot"))row.put("snapshot",old.get("snapshot")).put("snapshotAt",old.optLong("snapshotAt"));}
  else if(table.equals("bills")){row.put("amount",Ledger.amount(x,"amount",false)).put("due",text(x,"due",10)).put("kind",x.optString("kind","card")).put("accountId",text(x,"accountId",120));}
  else if(table.equals("subscriptions")){String due=text(x,"nextDue",10);row.put("amount",Ledger.amount(x,"amount",false)).put("nextDue",due).put("cycle",text(x,"cycle",10)).put("anchorDay",x.optInt("anchorDay",LocalDate.parse(due).getDayOfMonth())).put("category",text(x,"category",40)).put("accountId",text(x,"accountId",120)).put("active",x.optBoolean("active",true)).put("merchantKey",text(x,"merchantKey",120));if(old!=null&&old.has("lastPaidAt"))row.put("lastPaidAt",old.optLong("lastPaidAt"));}
  else throw new IllegalArgumentException("Unknown entity");JSONObject result=store.commit("Save "+table,new JSONArray().put(patch(table,row)));Reminders.schedule(host);return result.toString();
 }catch(Exception e){return error(e);}}
 @JavascriptInterface public String saveBill(String raw){try{return saveEntity(new JSONObject().put("table","bills").put("row",new JSONObject(raw)).toString());}catch(Exception e){return error(e);}}
 @JavascriptInterface public String saveSettings(String raw){try(Store store=new Store(host)){JSONObject in=new JSONObject(raw),cfg=store.settings();for(String key:Arrays.asList("cycleStartDay","monthBudget","categoryBudgets","reminders","captureNotifications","bankApps","emailApps","syncPreference"))if(in.has(key))cfg.put(key,in.get(key));for(String key:Arrays.asList("bankApps","emailApps")){JSONArray packages=cfg.optJSONArray(key);if(packages==null||packages.length()>50)throw new IllegalArgumentException("Check selected notification apps");for(int i=0;i<packages.length();i++)if(!packages.getString(i).matches("[a-zA-Z0-9_.]{3,120}"))throw new IllegalArgumentException("Invalid app package");}JSONObject snapshot=store.snapshot().put("settings",cfg);Ledger.validate(snapshot);store.setSettings(cfg);Reminders.schedule(host);return "{\"ok\":true}";}catch(Exception e){return error(e);}}
 @JavascriptInterface public void remember(String id,String category,boolean enabled){try(Store store=new Store(host)){JSONObject row=store.find(id);if(row==null||row.optString("source").equals("Manual")||!row.optString("kind").equals("expense")||category.length()>40)return;store.remember(row.optString("merchantKey"),category,enabled);}catch(Exception ignored){}}
 @JavascriptInterface public void permissions(){host.requestSms();}
 @JavascriptInterface public void notificationAccess(){host.requestNotificationAccess();}
 @JavascriptInterface public void notificationPermission(){host.requestNotificationPermission();}
 @JavascriptInterface public void importSms(){if(!granted(Manifest.permission.READ_SMS)){host.tell("Enable SMS permission first");return;}worker.execute(()->{int count=0;try(Cursor c=host.getContentResolver().query(Telephony.Sms.Inbox.CONTENT_URI,new String[]{"address","body","date","date_sent"},"date>=?",new String[]{String.valueOf(System.currentTimeMillis()-30L*86400000L)},"date DESC LIMIT 10000")){if(c!=null)while(c.moveToNext())if(Capture.ingest(host,c.getString(0),c.getString(1),(c.getLong(3)>0?c.getLong(3):c.getLong(2)),"SMS",false,c.getLong(2)))count++;host.tell(count+" records added or rechecked; review pending entries");host.refresh();}catch(Exception e){host.tell("Import stopped; saved records are safe. Retry is safe.");}});}
 @JavascriptInterface public String previewEmail(String text){try{String body=EmailText.decode(text);if(!EmailText.hasFinancialContext(body))throw new IllegalArgumentException("No bank/account/card context found in this email");SmsParser.Parsed p=SmsParser.parse("BANKALERT",body+" bank",System.currentTimeMillis());if(p!=null)return new JSONObject().put("ok",true).put("amount",p.amount).put("kind",p.kind).put("title",p.title).put("recordType","transaction").toString();JSONObject bill=NoticeParser.bill(body,"BANKALERT",System.currentTimeMillis());if(bill!=null)return new JSONObject().put("ok",true).put("amount",bill.getLong("amount")).put("kind","bill reminder").put("title",bill.getString("name")).put("recordType","bill").toString();throw new IllegalArgumentException("No supported transaction or bill found. Try the full bank email text.");}catch(Exception e){return error(e);}}
 @JavascriptInterface public String importEmail(String text){try{String body=EmailText.decode(text);JSONObject preview=new JSONObject(previewEmail(body));if(!preview.optBoolean("ok"))return preview.toString();boolean added=Capture.ingest(host,"BANKALERT",body,System.currentTimeMillis(),"Email",false);host.refresh();return added?new JSONObject().put("ok",true).put("recordType",preview.optString("recordType")).toString():"{\"ok\":false,\"error\":\"Already imported or no supported payment found\"}";}catch(Exception e){return error(e);}}
 @JavascriptInterface public void pickEmail(){host.pickDocument("email",null);}
 @JavascriptInterface public void exportSafetyBackup(){worker.execute(()->{try{java.io.File f=new java.io.File(host.getFilesDir(),"pre-restore.paisabackup");if(!f.isFile()||f.length()>32*1024*1024)throw new IllegalArgumentException("No valid safety copy available");try(java.io.FileInputStream in=new java.io.FileInputStream(f);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1)out.write(block,0,n);host.exportDocument(out.toByteArray(),"application/octet-stream","Paisa-before-restore.paisabackup",false);}}catch(Exception e){host.tell(e.getMessage());}});}
 @JavascriptInterface public void exportBackup(String password){char[] secret=password.toCharArray();worker.execute(()->{try(Store store=new Store(host)){byte[] bytes=BackupCipher.encrypt(store.backup().toString().getBytes(StandardCharsets.UTF_8),secret);host.exportDocument(bytes,"application/octet-stream","Paisa-"+LocalDate.now()+".paisabackup",true);}catch(Exception e){host.tell(e.getMessage());}finally{Arrays.fill(secret,'\0');}});}
 @JavascriptInterface public void restoreBackup(String password){if(password.length()<8){host.tell("Enter the backup password, at least 8 characters");return;}host.pickDocument("restore",password.toCharArray());}
 @JavascriptInterface public void exportCsv(){worker.execute(()->{try(Store store=new Store(host)){StringBuilder out=new StringBuilder("Date,Amount INR,Type,Description,Category,Account,Person,Source,Note,Loan ID,Destination account\r\n");JSONArray entries=store.entries();for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);if(!Ledger.active(e))continue;String[] values={Instant.ofEpochMilli(e.optLong("date")).atZone(ZoneId.systemDefault()).toLocalDateTime().toString(),java.math.BigDecimal.valueOf(e.optLong("amount"),2).toPlainString(),e.optString("kind"),e.optString("title"),e.optString("category"),e.optString("account"),e.optString("person"),e.optString("source"),e.optString("note"),e.optString("loanId"),e.optString("toAccountId")};for(int j=0;j<values.length;j++){if(j>0)out.append(',');String value=values[j];if(j!=1&&value.matches("^[=+@-].*"))value="'"+value;out.append('"').append(value.replace("\"","\"\"")).append('"');}out.append("\r\n");}host.exportDocument(out.toString().getBytes(StandardCharsets.UTF_8),"text/csv","paisa-transactions.csv",false);}catch(Exception e){host.tell("Export failed: "+e.getMessage());}});}
}
